// Shows ONLY doctor-approved familial screening indications (Rules 2 and 5).
// The raw Familial Risk agent output is never requested by this page.
import { isAxiosError } from 'axios'
import { useCallback, useEffect, useState } from 'react'

import { AiBadge } from '../../components/shared/AiBadge'
import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import { apiClient, type FamilyDto, type MemberDto } from '../../services/apiClient'

type ApprovedFamilialRiskDto = { caseId: string; screeningGuidance: string; approvedAt: string; disclaimer: string }

export function FamilyRiskPage() {
  const [members, setMembers] = useState<MemberDto[]>([])
  const [memberId, setMemberId] = useState('')
  const [risk, setRisk] = useState<ApprovedFamilialRiskDto | null>(null)
  const [status, setStatus] = useState<'loading' | 'ready' | 'none' | 'error'>('loading')

  useEffect(() => {
    void Promise.all([apiClient.get<FamilyDto>('/families/me'), apiClient.get<MemberDto>('/members/me')])
      .then(([family, mine]) => {
        const accessible = family.data.members.filter((item) => item.id === mine.data.id || item.role === 'MinorMember')
        setMembers(accessible); setMemberId(mine.data.id)
      })
      .catch(() => setStatus('error'))
  }, [])

  const load = useCallback(async () => {
    if (!memberId) return
    setStatus('loading'); setRisk(null)
    try {
      const { data } = await apiClient.get<ApprovedFamilialRiskDto>(`/members/${memberId}/familial-risk`)
      setRisk(data); setStatus('ready')
    } catch (error) {
      setStatus(isAxiosError(error) && error.response?.status === 404 ? 'none' : 'error')
    }
  }, [memberId])
  useEffect(() => { void load() }, [load])

  return (
    <div className="page-stack">
      <header className="page-header">
        <div>
          <p className="eyebrow">Familial screening <AiBadge label="AI-assisted · doctor-approved" /></p>
          <h1>Family screening indications</h1>
          <p>The Familial Risk agent reads consented family history only. A doctor reviews it, and approved screening indications appear here. This is not a diagnosis.</p>
        </div>
      </header>
      <label>Profile<select value={memberId} onChange={(event) => setMemberId(event.target.value)}>{members.map((member) => <option key={member.id} value={member.id}>{member.displayName}</option>)}</select></label>
      <section className="panel">
        {status === 'loading' ? <LoadingState label="Loading approved screening indication" />
          : status === 'error' ? <ErrorState message="Screening indication could not be loaded." onRetry={() => void load()} />
          : status === 'none' || !risk ? <EmptyState title="No approved screening indication" message="None has been approved for this profile yet. Run an AI triage; a doctor must approve before anything appears here." />
          : (
            <div className="approved-card" style={{ marginTop: 0 }}>
              <h2>Screening indication</h2>
              <p>{risk.screeningGuidance}</p>
              <p className="muted">Doctor-approved {new Date(risk.approvedAt).toLocaleString()} · {risk.disclaimer}</p>
              <p className="muted">Discuss screening with a licensed clinician in person.</p>
            </div>
          )}
      </section>
    </div>
  )
}
